//! The string helpers that came from uo-fonts' private `js` module (stage 5, D2) against V8:
//! `js/capture-text-v8.mjs` writes `tests/captures/text_v8.txt` (Node 24.15.0, Unicode 17.0;
//! deterministic, regenerated byte-identical when the module moved) and the tests below replay it,
//! unchanged from uo-fonts but for the paths of the functions: the `\s` set and `trim` over every
//! code point, `lower_cp` (the liang.ts rule) and `toLowerCase` over every non-surrogate code
//! point, the Final_Sigma contexts, `parseInt(s, 16)` on UTF-16 code units, ToUint8 and
//! `split(/\s+/)` with the empty pieces skipped (how uo-fonts reads it). Also: `parse_int_utf16`
//! equals `parse_int` (itself replayed against V8 in `tests/strings.rs`) on valid UTF-16 for every
//! radix, and the uo-opc helpers (`js_space_len`, `\w`, the object key order, the byte decoders)
//! against their definitions.
#![allow(clippy::unwrap_used, clippy::panic)]

use std::collections::HashMap;

use uo_alloc::assert_no_leak;
use uo_jsnum::conv::to_uint8;
use uo_jsnum::object::{array_index, js_object_order};
use uo_jsnum::parse::{parse_int, parse_int_utf16};
use uo_jsnum::text::{
    decode_latin1, decode_utf8, is_js_space, is_js_space_unit, is_js_word, js_space_len, lower_cp, split_js_space, to_lowercase, trim,
};
use uo_testkit::generate::Rng;

const EXPECTED: &str = include_str!("captures/text_v8.txt");

fn cps(field: &str) -> Vec<u32> {
    if field == "-" { Vec::new() } else { field.split(',').map(|h| u32::from_str_radix(h, 16).unwrap()).collect() }
}

fn text(field: &str) -> String {
    cps(field).into_iter().map(|c| char::from_u32(c).unwrap()).collect()
}

fn units(field: &str) -> Vec<u16> {
    cps(field).into_iter().map(|c| u16::try_from(c).unwrap()).collect()
}

fn set_of(ranges: &str) -> Vec<bool> {
    let mut set = vec![false; 0x11_0000];
    for r in ranges.split(',') {
        let (a, b) = r.split_once('-').unwrap();
        for cp in u32::from_str_radix(a, 16).unwrap()..=u32::from_str_radix(b, 16).unwrap() {
            set[cp as usize] = true;
        }
    }
    set
}

fn lines(kind: &'static str) -> impl Iterator<Item = Vec<&'static str>> {
    EXPECTED.lines().filter_map(move |l| {
        let mut it = l.split('\t');
        (it.next() == Some(kind)).then(|| it.collect())
    })
}

fn js_number(bits: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(bits, 16).unwrap())
}

fn same(a: f64, b: f64) -> bool {
    (a.is_nan() && b.is_nan()) || a.to_bits() == b.to_bits()
}

/// `s.split(/\s+/).filter(Boolean)`: the pieces uo-fonts reads.
fn tokens(s: &str) -> Vec<&str> {
    split_js_space(s).filter(|t| !t.is_empty()).collect()
}

/// `parseInt(s, 16)` over code units (what uo-fonts calls).
fn parse_int_hex(units: &[u16]) -> f64 {
    parse_int_utf16(units, 16)
}

#[test]
fn expected_file_names_its_origin() {
    let head: Vec<&str> = EXPECTED.lines().take(2).collect();
    assert!(head[0].starts_with("@node v"), "{head:?}");
    assert!(head[1].starts_with("@unicode "), "{head:?}");
    assert!(EXPECTED.ends_with('\n') && !EXPECTED.contains('\r'));
}

#[test]
fn whitespace_matches_v8_over_every_code_point() {
    let space = set_of(lines("space").next().unwrap()[0]);
    let trim_set = set_of(lines("trim").next().unwrap()[0]);
    assert_eq!(space, trim_set);
    let mut wrong = Vec::new();
    for cp in 0..0x11_0000u32 {
        let as_char = char::from_u32(cp).is_some_and(is_js_space);
        if as_char != space[cp as usize] {
            wrong.push(cp);
        }
        if let Ok(u) = u16::try_from(cp)
            && is_js_space_unit(u) != space[cp as usize]
        {
            wrong.push(cp);
        }
        if let Some(c) = char::from_u32(cp) {
            let s = c.to_string();
            if trim(&s).is_empty() != trim_set[cp as usize] {
                wrong.push(cp);
            }
            if (js_space_len(s.as_bytes(), 0) == s.len()) != space[cp as usize] {
                wrong.push(cp);
            }
        }
    }
    assert!(wrong.is_empty(), "differences from V8 at {wrong:x?}");
}

#[test]
fn lower_cp_matches_v8_over_every_code_point() {
    let expected: HashMap<u32, u32> =
        lines("lower").map(|f| (u32::from_str_radix(f[0], 16).unwrap(), u32::from_str_radix(f[1], 16).unwrap())).collect();
    let mut wrong = Vec::new();
    for cp in (0..0x11_0000u32).filter_map(char::from_u32).map(u32::from) {
        let want = expected.get(&cp).copied().unwrap_or(cp);
        let got = u32::from(lower_cp(char::from_u32(cp).unwrap()));
        if got != want {
            wrong.push((cp, got, want));
        }
    }
    assert!(expected.len() > 1_000);
    assert!(wrong.is_empty(), "lowerCp differs from V8 (cp, rust, v8): {wrong:x?}");
    assert_eq!(lower_cp('\u{130}'), '\u{130}');
    assert_eq!(lower_cp('A'), 'a');
    assert_eq!(lower_cp('\u{3a3}'), '\u{3c3}');
}

#[test]
fn to_lowercase_matches_v8_over_every_code_point() {
    let expected: HashMap<u32, String> = lines("lowerstr").map(|f| (u32::from_str_radix(f[0], 16).unwrap(), text(f[1]))).collect();
    let mut wrong = Vec::new();
    for c in (0..0x11_0000u32).filter_map(char::from_u32) {
        let s = c.to_string();
        let want = expected.get(&u32::from(c)).cloned().unwrap_or_else(|| s.clone());
        let got = to_lowercase(&s);
        if got != want {
            wrong.push((u32::from(c), got, want));
        }
    }
    assert!(expected.len() > 1_000);
    assert!(wrong.is_empty(), "toLowerCase differs from V8 (cp, rust, v8): {wrong:x?}");
}

#[test]
fn final_sigma_contexts_match_v8() {
    let mut n = 0;
    let mut wrong = Vec::new();
    for f in lines("sigma") {
        let (input, want) = (text(f[0]), text(f[1]));
        let got = to_lowercase(&input);
        if got != want {
            wrong.push((input, got, want));
        }
        n += 1;
    }
    assert!(n > 1_500);
    assert!(wrong.is_empty(), "Final_Sigma differs from V8 (input, rust, v8): {wrong:?}");
    assert_eq!(to_lowercase("\u{3a3}"), "\u{3c3}");
    assert_eq!(to_lowercase("A\u{3a3}"), "a\u{3c2}");
    assert_eq!(to_lowercase("A\u{3a3}A"), "a\u{3c3}a");
}

#[test]
fn parse_int_matches_v8() {
    let mut n = 0;
    let mut wrong = Vec::new();
    for f in lines("pi2") {
        let u1 = u16::from_str_radix(f[0], 16).unwrap();
        let results: Vec<&str> = f[1].split(',').collect();
        assert_eq!(results.len(), 128);
        for (u2, want) in results.iter().enumerate() {
            let got = parse_int_hex(&[u1, u2 as u16]);
            if !same(got, js_number(want)) {
                wrong.push((u1, u2, got, *want));
            }
            n += 1;
        }
    }
    for f in lines("pi") {
        let u = units(f[0]);
        let got = parse_int_hex(&u);
        if !same(got, js_number(f[1])) {
            wrong.push((0xFFFF, u.len(), got, f[1]));
        }
        n += 1;
    }
    assert!(n > 20_000, "{n}");
    assert!(wrong.is_empty(), "parseInt differs from V8 (u1, u2 or units, rust, v8): {wrong:?}");
}

#[test]
fn parse_int_cases_by_hand() {
    let p = |s: &str| parse_int_hex(&s.encode_utf16().collect::<Vec<u16>>());
    assert_eq!(p("ff"), 255.0);
    assert_eq!(p("1g"), 1.0);
    assert_eq!(p("-1"), -1.0);
    assert!(p("-0").is_sign_negative() && p("-0") == 0.0);
    assert!(p("").is_nan() && p("g").is_nan() && p("0x").is_nan() && p("-").is_nan());
    assert_eq!(p(" \u{a0}0x1f"), 31.0);
    assert_eq!(p(&"f".repeat(300)), f64::INFINITY);
    assert_eq!(p(&format!("-{}", "f".repeat(300))), f64::NEG_INFINITY);
    assert!(parse_int_hex(&[0xD83D, 0x31]).is_nan());
    assert_eq!(parse_int_hex(&[0x31, 0xD83D]), 1.0);
}

/// On valid UTF-16 the code-unit parser is `parse_int` of the same text, for every radix
/// (`parse_int` is replayed against V8 in `tests/strings.rs`); a lone surrogate behaves as a
/// non-space, non-digit character (U+FFFD in its place gives the same result).
#[test]
fn parse_int_utf16_equals_parse_int_on_every_radix() {
    const ALPHABET: [&str; 30] = [
        "0",
        "1",
        "7",
        "9",
        "a",
        "f",
        "g",
        "z",
        "Z",
        "x",
        "X",
        "+",
        "-",
        ".",
        "e",
        " ",
        "\t",
        "\u{a0}",
        "\u{feff}",
        "\u{3000}",
        "\u{85}",
        "\u{180e}",
        "\u{e9}",
        "\u{661}",
        "\u{ff11}",
        "\u{1f600}",
        "00",
        "0x",
        "ffffffffffffffff",
        "zzzzzzzzzzzz",
    ];
    let radixes = [0, 1, 2, 3, 7, 8, 10, 16, 32, 36, 37, -1, i32::MIN];
    let mut rng = Rng::new(0x5EED_D200);
    let mut n = 0;
    for _ in 0..40_000 {
        let len = rng.below(10);
        let s: String = (0..len).map(|_| ALPHABET[rng.below(ALPHABET.len())]).collect();
        let u: Vec<u16> = s.encode_utf16().collect();
        for radix in radixes {
            let (a, b) = (parse_int(&s, radix), parse_int_utf16(&u, radix));
            assert!(same(a, b), "parse_int({s:?}, {radix}) = {a}, parse_int_utf16 = {b}");
            n += 1;
        }
        // a lone surrogate at a random place reads like any non-space, non-digit character
        let at = rng.below(u.len() + 1);
        let mut lone = u.clone();
        lone.insert(at, 0xDC00);
        let mut replaced = u.clone();
        replaced.insert(at, 0xFFFD);
        let replaced = String::from_utf16_lossy(&replaced);
        for radix in radixes {
            assert!(same(parse_int_utf16(&lone, radix), parse_int(&replaced, radix)), "{lone:x?} radix {radix}");
        }
    }
    assert!(n > 500_000);
    // 400 digits of radix 10 (Infinity past 309) and 1,100 of radix 2 (rounding past 53 bits)
    for s in ["1".repeat(400), format!("-{}", "1".repeat(1_100)), format!("  0x{}", "f".repeat(260))] {
        let u: Vec<u16> = s.encode_utf16().collect();
        for radix in radixes {
            assert!(same(parse_int(&s, radix), parse_int_utf16(&u, radix)), "{radix}");
        }
    }
}

#[test]
fn to_uint8_matches_v8() {
    let mut n = 0;
    let mut wrong = Vec::new();
    for f in lines("u8") {
        let x = js_number(f[0]);
        let want: u8 = f[1].parse().unwrap();
        if to_uint8(x) != want {
            wrong.push((f[0], to_uint8(x), want));
        }
        n += 1;
    }
    assert!(n > 400);
    assert!(wrong.is_empty(), "ToUint8 differs from V8 (value, rust, v8): {wrong:?}");
    assert_eq!(to_uint8(-1.0), 255);
    assert_eq!(to_uint8(f64::NAN), 0);
    assert_eq!(to_uint8(f64::NEG_INFINITY), 0);
    assert_eq!(to_uint8(256.9), 0);
    assert_eq!(to_uint8(-255.9), 1);
}

#[test]
fn split_matches_v8() {
    let mut n = 0;
    let mut wrong = Vec::new();
    for f in lines("split") {
        let input = text(f[0]);
        let want: Vec<String> = if f[1] == "-" { Vec::new() } else { f[1].split(';').map(text).collect() };
        let got = tokens(&input);
        if got != want {
            wrong.push((input.clone(), got.iter().map(|s| s.to_string()).collect::<Vec<_>>(), want));
        }
        n += 1;
    }
    assert!(n > 700);
    assert!(wrong.is_empty(), "split differs from V8 (input, rust, v8): {wrong:?}");
    assert_eq!(trim("\u{feff} a b \u{2028}"), "a b");
    assert_eq!(trim("\u{85}a\u{180e}"), "\u{85}a\u{180e}");
    assert_eq!(trim(""), "");
}

/// The uo-opc helpers, against their definitions: `\w` is `[A-Za-z0-9_]` and no byte of a
/// multi-byte character; an array index is the canonical form of an integer below 2^32 - 1;
/// the key order puts the indices first, ascending, the rest in insertion order; the decoders.
#[test]
fn opc_helpers_by_definition() {
    for b in 0..=255u8 {
        assert_eq!(is_js_word(b), b.is_ascii_alphanumeric() || b == b'_', "{b:#x}");
    }
    for v in [0u64, 1, 9, 10, 4_294_967_293, 4_294_967_294] {
        assert_eq!(array_index(&v.to_string()), Some(v as u32));
    }
    for k in ["", "4294967295", "4294967296", "99999999999", "01", "00", "-0", "-1", "+1", "1.0", "1e3", " 1", "1 ", "\u{661}", "a"] {
        assert_eq!(array_index(k), None, "{k:?}");
    }
    let order = |keys: &[&str]| -> Vec<String> {
        js_object_order(keys.iter().map(|k| (k.to_string(), ())).collect()).into_iter().map(|(k, ())| k).collect()
    };
    assert_eq!(order(&["b", "10", "a", "2", "01", "4294967295", "0"]), ["0", "2", "10", "b", "a", "01", "4294967295"]);
    assert_eq!(order(&["z", "y"]), ["z", "y"]);
    assert_eq!(decode_utf8(b"\xEF\xBB\xBFa\xEF\xBB\xBF"), "a\u{feff}");
    assert_eq!(decode_utf8(b"a\xF0\x9F\x98b\xC0\xAF"), "a\u{fffd}b\u{fffd}\u{fffd}");
    assert_eq!(decode_latin1(&[0x41, 0xE9, 0xFF, 0x00]), "A\u{e9}\u{ff}\u{0}");
}

#[test]
fn m1_no_leak() {
    assert_no_leak(|| is_js_space(' '));
    assert_no_leak(|| is_js_space_unit(0x20));
    assert_no_leak(|| trim("  a  ").len());
    assert_no_leak(|| tokens(" a  b ").len());
    assert_no_leak(|| lower_cp('\u{130}'));
    assert_no_leak(|| to_lowercase("A\u{3a3} B"));
    assert_no_leak(|| parse_int_hex(&[0x30, 0x78, 0x66, 0x66]));
    assert_no_leak(|| parse_int_hex(&"f".repeat(100).encode_utf16().collect::<Vec<u16>>()));
    assert_no_leak(|| to_uint8(-1.0));
}
